import {
  WatchtowerApiCell,
  WatchtowerApiColumnGroup,
  WatchtowerApiRow,
} from './DrillDownTable.api.types';
import {
  DrillDownCell,
  DrillDownCellType,
  DrillDownColumnGroup,
  DrillDownRow,
  DrillDownSubColumn,
} from './DrillDownTable.types';

function mapVariationDirection(
  direction?: 'up' | 'down' | 'neutral',
): DrillDownCellType {
  if (direction === 'up') return 'positive';
  if (direction === 'down') return 'negative';
  if (direction === 'neutral') return 'neutral';
  return 'default';
}

function mapApiCell(apiCell?: WatchtowerApiCell | null): DrillDownCell {
  if (apiCell == null) {
    return { value: null, type: 'empty' };
  }

  const displayValue =
    apiCell.unit_measure && apiCell.value != null
      ? `${apiCell.value}${apiCell.unit_measure}`
      : apiCell.value;

  return {
    value: displayValue ?? null,
    type: mapVariationDirection(apiCell.variation_direction),
    tooltip: apiCell.tooltip,
  };
}

function mapApiRow(apiRow: WatchtowerApiRow): DrillDownRow {
  const cells: Record<string, DrillDownCell> = {};
  for (const [key, apiCell] of Object.entries(apiRow.cells)) {
    cells[key] = mapApiCell(apiCell);
  }

  return {
    id: apiRow.id,
    parentId: apiRow.parent_id,
    level: apiRow.level,
    hasChildren: apiRow.has_children,
    label: apiRow.label,
    tooltipContent: apiRow.tooltip,
    logoSrc: apiRow.brand_logo ?? undefined,
    cells,
  };
}

function mapApiColumnGroup(
  apiGroup: WatchtowerApiColumnGroup,
): DrillDownColumnGroup {
  const columns: DrillDownSubColumn[] = apiGroup.columns.map((col) => ({
    id: col.id,
    title: col.title,
    tooltipContent: col.tooltip,
  }));

  return {
    id: apiGroup.id,
    title: apiGroup.title,
    unit: apiGroup.unit ? `[ ${apiGroup.unit} ]` : undefined,
    tooltipContent: apiGroup.tooltip,
    columns,
  };
}

type VisibleTreeNode = {
  id: string;
  parentId: string | null;
  hasChildren: boolean;
};

export function buildVisibleRows<T extends VisibleTreeNode>(
  allRows: T[],
  expandedIds: Set<string>,
  parentId: string | null = null,
): T[] {
  const result: T[] = [];
  for (const row of allRows.filter((r) => r.parentId === parentId)) {
    result.push(row);
    if (row.hasChildren && expandedIds.has(row.id)) {
      result.push(...buildVisibleRows(allRows, expandedIds, row.id));
    }
  }
  return result;
}

export function mapWatchtowerApiRows(
  apiRows: WatchtowerApiRow[],
): DrillDownRow[] {
  return apiRows.map(mapApiRow);
}

export function mapWatchtowerApiColumnGroups(
  apiGroups: WatchtowerApiColumnGroup[],
): DrillDownColumnGroup[] {
  return apiGroups.map(mapApiColumnGroup);
}
